#include <deque>
#include <iostream>

int main() {
  std::deque<int> d{1, 2, 3, 4};
  auto it = d.begin() + 2;  // refers to 3
  d.erase(d.begin());
  std::cout << *it << '\n';
}

#include <iostream>
#include <unordered_map>

int main() {
  std::unordered_map<int, int> m{{1, 10}};
  auto it = m.find(1);
  int& r = it->second;
  m.reserve(1000);
  std::cout << r << '\n';          // use A
  std::cout << it->second << '\n'; // use B
}

#include <iostream>
#include <vector>

int main() {
  std::vector<int> a{1, 2, 3}, b{4, 5};
  auto it = a.begin();
  a.swap(b);
  std::cout << *it << ' ' << (it == b.begin()) << '\n';
}

#include <vector>

