  std::vector<int> v{1, 2, 3, 4};
  [[maybe_unused]] auto a = v.begin();
  auto b = a + 1;
  [[maybe_unused]] auto c = a + 2;
  v.erase(b);
}

#include <iostream>
#include <utility>
#include <vector>

int main() {
  std::vector<int> v{1, 2, 3};
  int* p = v.data();
  std::vector<int> w = std::move(v);
  std::cout << *p << ' ' << (p == w.data()) << '\n';
}
